    "claim": "The design is balanced: for every brand the number of men's jeans and the number of women's jeans both have a minimum of 2 and a maximum of 2.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.groupby([measurements.brand.str.strip().str.lower(), 'menWomen']).size().unstack().agg(['min', 'max'])"
  },
  {
    "id": "front-pocket-means",
    "claim": "Men's jeans average a maximum front pocket height of 23.13 and a minimum front height of 18.08, against 14.33 and 13.23 for women's; front widths are much closer, 16.37 vs 15.18 at the maximum and 13.36 vs 12.26 at the minimum.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.groupby('menWomen')[['maxHeightFront', 'minHeightFront', 'maxWidthFront', 'minWidthFront']].mean().round(2)"
  },
