    "id": "front-height-ratio",
    "claim": "The average men's front pocket is 1.61 times as tall as the average women's front pocket, 61.44% taller.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.groupby('menWomen').maxHeightFront.mean().pipe(lambda s: pd.Series({'ratio': s['men'] / s['women'], 'pct_taller': 100 * (s['men'] / s['women'] - 1)})).round(2)"
  },
  {
    "id": "gap-is-front-and-vertical",
    "claim": "The gap lives in front pocket height and almost nowhere else: the men's-to-women's ratio of means is 1.61 for maximum front height, 1.08 for maximum front width, 1.06 for maximum back height and 1.03 for maximum back width.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.groupby('menWomen')[['maxHeightFront', 'maxWidthFront', 'maxHeightBack', 'maxWidthBack']].mean().pipe(lambda g: pd.Series({c: g.loc['men', c] / g.loc['women', c] for c in g.columns})).round(2)"
  },
  {
    "id": "front-pocket-area",
    "claim": "Taking maximum height times maximum width as a rough pocket area, men's front pockets average 378.41 and women's 217.97, a ratio of 1.74.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.assign(front_area=measurements.maxHeightFront * measurements.maxWidthFront).groupby('menWomen').front_area.mean().pipe(lambda s: pd.Series({'men': s['men'], 'women': s['women'], 'ratio': s['men'] / s['women']})).round(2)"
