    "tables": {"measurements": "data/measurements.csv"},
    "code": "pd.Series({'men_min': measurements.query(\"menWomen == 'men'\").maxHeightFront.min(), 'women_below': (measurements.query(\"menWomen == 'women'\").maxHeightFront < measurements.query(\"menWomen == 'men'\").maxHeightFront.min()).sum(), 'women_total': (measurements.menWomen == 'women').sum()}, dtype=object)"
