  },
  {
    "id": "min-above-max-rows",
    "claim": "In 14 rows the recorded minimum front height is larger than the recorded maximum front height, 12 of them women's jeans and 2 men's.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "pd.Series({'rows': int((measurements.minHeightFront > measurements.maxHeightFront).sum()), 'women': int(((measurements.minHeightFront > measurements.maxHeightFront) & (measurements.menWomen == 'women')).sum()), 'men': int(((measurements.minHeightFront > measurements.maxHeightFront) & (measurements.menWomen == 'men')).sum())})"
  },
  {
    "id": "boot-named-straight",
    "claim": "Six women's jeans are labelled style 'straight' although their product names contain 'boot': Arizona Perfect Boot, Lucky Sweet Boot, Levi's Classic Bootcut, 7 for All Mankind Bootcut, Guess Tailored Mini Boot and Express Barely Boot Midrise.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements[measurements.style.eq('straight') & measurements.name.str.lower().str.contains('boot')][['brand', 'menWomen', 'name', 'style']]"
  }
]

